import pandas as pd

def compute_signal(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy()
    df["signal"] = (df["revt"] - df["cogs"]) / df["at"]
    df = df[
        df["revt"].notna()
        & df["cogs"].notna()
        & df["at"].notna()
        & (df["at"] != 0)
        & df["signal"].notna()
        & df["signal"].map(lambda x: float("inf") > x > float("-inf"))
    ]
    return df[["permno", "time_avail_m", "signal"]].rename(
        columns={"time_avail_m": "yyyymm"}
    )
